function addr(x) {
  if (!x) return '';
  if (typeof x === 'string') {
    const m = x.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
    return (m ? m[0] : x).trim();
  }
  if (x.text) return addr(x.text);
  if (Array.isArray(x.value) && x.value[0]) return addr(x.value[0].address || x.value[0]);
  if (x.address) return String(x.address).trim();
  return String(x).trim();
}
function looksLikeApplication(hay) {
  const lower = String(hay || '').toLowerCase();
  const needles = [
    'i am applying', "i'm applying", 'please find my', 'attached cv', 'attached resume',
    'curriculum vitae', ' resume', ' cv ', 'application for',
    'i would like to join', 'i want to intern', 'cover letter'
  ];
  if (needles.some((n) => lower.includes(n))) return true;
  return lower.includes('apply') && (lower.includes('role') || lower.includes('intern') || lower.includes('job'));
}
const m = $input.first().json || {};
const meta = m.metadata || {};
const from = addr(m.from || meta.from || m.fromAddress || '').toLowerCase();
const subject = String(m.subject || meta.subject || '').trim();
let body = String(m.textPlain || m.text || m.textAsHtml || '').trim();
if (!body && (m.html || m.textHtml)) {
  body = String(m.html || m.textHtml).replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}
if (!from) return [];
if (from === 'info@themobileprof.com') return [];
if (/mailer-daemon|no-?reply|postmaster|notifications@|newsletter@|bounce@/i.test(from)) return [];
if (/n8n smoke/i.test(subject)) return [];
if (!body) body = '(empty body)';
if (looksLikeApplication(subject + ' ' + body)) return [];
body = body.slice(0, 8000);
return [{ json: { from, subject, body } }];

function deskSetting(key, fallback) {
  try {
    const s = $('Fetch desk settings').first().json || {};
    const v = s[key];
    if (v != null && String(v).trim() !== '') return String(v).trim();
  } catch (e) {}
  return fallback;
}
const prep = $('Prepare inbound').first().json || {};
const from = String(prep.from || '').trim();
const subject = String(prep.subject || '').trim();
const body = String(prep.body || '').slice(0, 8000);
let projects = [];
try {
  const raw = $('Fetch projects').first().json || {};
  const list = Array.isArray(raw.projects) ? raw.projects : [];
  projects = list.map((p) => ({ slug: String(p.slug || '').trim(), name: String(p.name || '').trim() })).filter((p) => p.slug || p.name);
} catch (e) {}
let existing_contact = null;
try {
  const desk = $('Search desk CRM').first().json || {};
  if (desk.known === true || desk.known === 'true') {
    const c = desk.contact || {};
    existing_contact = {
      contact_id: c.id != null ? String(c.id) : '',
      contact_name: String(c.name || '').trim(),
      company_name: String(c.company || '').trim(),
      email: String(c.email || '').trim(),
      phone: String(c.phone || '').trim(),
      notes: String(c.notes || '').trim().slice(0, 2000),
      stage: String(c.stage || '').trim(),
      offer: String(c.offer || '').trim(),
      timeline: Array.isArray(c.timeline) ? c.timeline : [],
      source: 'desk'
    };
  }
} catch (e) {}
if (!existing_contact) {
  try {
    const res = $('Search Books').first().json || {};
    const list = Array.isArray(res.contacts) ? res.contacts : [];
    const want = from.toLowerCase();
    let hit = list.find((c) => String(c.email || '').toLowerCase() === want) || list[0];
    if (hit && hit.contact_id) {
      existing_contact = {
        contact_id: String(hit.contact_id),
        contact_name: String(hit.contact_name || '').trim(),
        company_name: String(hit.company_name || '').trim(),
        email: String(hit.email || '').trim(),
        phone: String(hit.phone || hit.mobile || '').trim(),
        notes: String(hit.notes || '').trim().slice(0, 2000)
      };
    }
  } catch (e) {}
}
const task = [
  'Inbound email to info@. File a short thread summary. Do not draft a reply. Do not send.',
  'Use task_type noise, file_thread, or important.',
  'notify true only if a human must look now. project_slug only from the projects list in context.',
  '',
  'From: ' + from,
  'Subject: ' + (subject || '(no subject)'),
  '',
  'Their message:',
  body || '(empty body)'
].join('\n');
return [{ json: {
  from,
  subject,
  body,
  organization_id: deskSetting('zoho.organization_id', '939049468'),
  task_description: task,
  context_data: {
    channel: 'email',
    department: 'crm',
    from,
    subject,
    correspondence: body,
    projects,
    existing_contact
  }
} }];

const worker = $input.first().json || {};
const prep = $('Prepare inbound').item.json || {};
const sd = worker.structured_data || {};
const task = String(sd.task_type || '').toLowerCase();
const notify = sd.notify === true || sd.notify === 'true' || task === 'important';
const noise = task === 'noise';
const record = !noise && (sd.record_lead === true || sd.record_lead === 'true' || task === 'file_thread' || task === 'important');
let email = String(sd.email || prep.from || '').trim();
let name = String(sd.contact_name || sd.name || '').trim();
if (!name && email.includes('@')) name = email.split('@')[0];
const notes = String(sd.notes || '').trim();
const project_slug = String(sd.project_slug || '').trim();
let ping = String(worker.output_text || sd.notify_reason || '').trim();
ping = ping.replace(/^#{1,6}\s+/gm, '').replace(/\*\*/g, '').trim();
if (ping.length > 3500) ping = ping.slice(0, 3490) + '…';
const lines = ['info@ looks important.', 'From: ' + (prep.from || ''), 'Subject: ' + (prep.subject || '(no subject)')];
if (project_slug) lines.push('Bet: ' + project_slug);
lines.push('', ping || String(sd.notify_reason || 'A human should look at this thread.'), '', 'This bot did not send mail. Reply yourself or /crm follow up.');
return [{ json: {
  record,
  notify,
  project_slug,
  ping_text: lines.join('\n'),
  crm_contact: record ? {
    contact_name: name,
    email,
    phone: String(sd.phone || '').trim(),
    company_name: String(sd.company_name || '').trim(),
    pipeline_stage: String(sd.pipeline_stage || 'new'),
    next_action: String(sd.next_action || '').trim(),
    notes: (notes || ('Inbound: ' + (prep.subject || ''))).slice(0, 800),
    source: 'email'
  } : null
} }];

const d = $('Decide').first().json || {};
const raw = $input.first().json || {};
const list = Array.isArray(raw.people) ? raw.people : [];
const text = String(d.ping_text || '').trim();
if (!text) return [];
const seen = {};
const items = [];
for (const p of list) {
  const chat_id = String((p && p.telegram_id) || '').replace(/\D/g, '');
  if (!chat_id || seen[chat_id]) continue;
  seen[chat_id] = true;
  items.push({ json: { chat_id, text } });
}
return items;
